            <div className="space-y-4 animate-fade-in">
                <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm"><h2 className="text-xl font-bold text-gray-800 flex items-center gap-2"><IconHistory className="w-6 h-6" /> {t.auditLogs}</h2></div>
                <div className="bg-white rounded-2xl border border-gray-200 overflow-hidden"><table className="w-full text-start text-sm"><thead className="bg-gray-50 text-gray-500"><tr><th className="px-4 py-3">{t.time}</th><th className="px-4 py-3">{t.user}</th><th className="px-4 py-3">{t.operation}</th><th className="px-4 py-3">{t.entity}</th><th className="px-4 py-3">{t.details}</th><th className="px-4 py-3">{t.action}</th></tr></thead><tbody className="divide-y divide-gray-100">{systemLogs.map(log => (<tr key={log.id} className="hover:bg-gray-50"><td className="px-4 py-3 text-gray-500 dir-ltr text-right">{new Date(log.timestamp).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</td><td className="px-4 py-3 font-bold text-gray-700">{log.actorName}</td><td className="px-4 py-3"><span className={`px-2 py-1 rounded text-xs font-bold ${log.actionType === 'DELETE' ? 'bg-red-100 text-red-700' : (log.actionType === 'CREATE' ? 'bg-green-100 text-green-700' : 'bg-blue-100 text-blue-700')}`}>{log.actionType}</span></td><td className="px-4 py-3">{log.entity}</td><td className="px-4 py-3 text-gray-600 truncate max-w-xs" title={log.details}>{log.details}</td><td className="px-4 py-3">{log.actionType === 'DELETE' && log.backupData && (<button onClick={() => handleRestore(log)} className="text-blue-600 hover:bg-blue-50 px-2 py-1 rounded flex items-center gap-1 font-bold text-xs"><IconRefreshCw className="w-3 h-3" /> {t.restore}</button>)}</td></tr>))}</tbody></table></div></div>
        )}
        {activeTab === 'financial' && (isAdmin || isMaster) && renderFinancialReport()}
      </div>
      {selectedTicket && renderTicketModal()}
    </div>
  );
};

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { InternalMessage, Personnel, AttachedFile } from '../types';
import { IconMail, IconSend, IconInbox, IconPaperclip, IconTrash, IconFile, IconReply, IconPlus, IconSearch, IconUsers, IconArrowRight, IconHistory } from './Icons';
import { sendInternalMessage, updateMessageInCloud, deleteMessageFromCloud, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  messages: InternalMessage[];
  lang: Language;
}

export const InternalMessenger: React.FC<Props> = ({ currentUser, personnel, messages, lang }) => {
  const [activeTab, setActiveTab] = useState<'inbox' | 'sent'>('inbox');
  const [selectedMsgId, setSelectedMsgId] = useState<string | null>(null);
  const [isComposeOpen, setIsComposeOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);

  // Compose State
  const [recipientIds, setRecipientIds] = useState<string[]>([]);
  const [subject, setSubject] = useState('');
  const [body, setBody] = useState('');
  const [attachments, setAttachments] = useState<AttachedFile[]>([]);
  const [isSending, setIsSending] = useState(false);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const isMaster = currentUser.username === 'master';

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  const t = {
      fa: {
          inbox: 'صندوق ورودی',
          sent: 'پیام‌های ارسالی',
          compose: 'نوشتن پیام جدید',
          search: 'جستجو در مکاتبات...',
          subject: 'موضوع پیام',
          body: 'متن پیام',
          recipients: 'ارسال به:',
          send: 'ارسال پیام',
          reply: 'پاسخ سریع',
          delete: 'حذف',
          files: 'فایل‌های پیوست',
          cancel: 'انصراف',
          writeHere: 'اینجا بنویسید...',
          from: 'از طرف:',
          to: 'ارسال شده به:',
          noSelect: 'برای مشاهده محتوا، یک پیام را از لیست انتخاب کنید.',
          empty: 'هنوز پیامی در این بخش وجود ندارد.'
      },
      en: {
          inbox: 'Inbox',
          sent: 'Sent',
          compose: 'Compose New',
          search: 'Search messages...',
          subject: 'Subject',
          body: 'Body',
          recipients: 'To:',
          send: 'Send Message',
          reply: 'Quick Reply',
          delete: 'Delete',
          files: 'Attachments',
          cancel: 'Cancel',
          writeHere: 'Write your message...',
          from: 'From:',
          to: 'To:',
          noSelect: 'Select a message from the list to read.',
          empty: 'No messages here yet.'
      }
  }[lang];

  const filteredMessages = useMemo(() => {
      let list = activeTab === 'inbox' 
          ? messages.filter(m => m.recipientIds.includes(currentUser.id))
          : messages.filter(m => m.senderId === currentUser.id);

      if (searchTerm.trim()) {
          const term = searchTerm.toLowerCase();
          list = list.filter(m => 
              m.subject.toLowerCase().includes(term) || 
              m.body.toLowerCase().includes(term) ||
              m.senderName.toLowerCase().includes(term)
          );
      }
      return list.sort((a,b) => new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime());
  }, [messages, activeTab, currentUser.id, searchTerm]);

  const selectedMessage = useMemo(() => 
    messages.find(m => m.id === selectedMsgId) || null
  , [messages, selectedMsgId]);

  const handleSendMessage = async () => {
      if (recipientIds.length === 0 || !subject.trim() || !body.trim()) return;
      setIsSending(true);
      try {
          const recipientNames = recipientIds.map(id => personnel.find(p => p.id === id)?.fullName || 'Unknown');
          const newMessage: InternalMessage = { 
              id: `msg-${Date.now()}`, 
              senderId: currentUser.id, 
              senderName: currentUser.fullName, 
              recipientIds, 
              recipientNames, 
              subject, 
              body, 
              files: attachments.filter(f => f.status === 'success'), 
              createdAt: new Date().toISOString(), 
              readBy: [] 
          };
          await sendInternalMessage(newMessage);
          setIsComposeOpen(false);
          setRecipientIds([]); setSubject(''); setBody(''); setAttachments([]);
          setActiveTab('sent');
          if (!isMobile) setSelectedMsgId(newMessage.id);
      } catch (e) { alert('Error!'); } finally { setIsSending(false); }
  };

  const handleSelectMessage = (msg: InternalMessage) => {
      setSelectedMsgId(msg.id);
      if (activeTab === 'inbox' && !msg.readBy.includes(currentUser.id)) {
          updateMessageInCloud(msg.id, { readBy: [...msg.readBy, currentUser.id] });
      }
  };

  const handleFileSelect = async (e: React.ChangeEvent<HTMLInputElement>) => {
      if (e.target.files?.[0]) {
          const file = e.target.files[0];
          const newFile: AttachedFile = { name: file.name, size: file.size, type: file.type, content: '', status: 'uploading', progress: 0 };
          setAttachments(prev => [...prev, newFile]);
          uploadFileWithProgress(file, (progress) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, progress } : f)), (url) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, content: url, status: 'success', progress: 100 } : f)), (err) => setAttachments(prev => prev.map(f => f.name === file.name ? { ...f, status: 'error' } : f)));
      }
  };

  return (
    <div className="bg-white rounded-3xl border border-gray-200 shadow-xl flex h-[750px] w-full overflow-hidden animate-fade-in relative ring-1 ring-black/5">

        {/* --- Sidebar (Message List) --- */}
        <div className={`flex flex-col border-l border-gray-100 bg-white transition-all duration-300 ${isMobile && selectedMsgId ? 'hidden' : 'w-full md:w-[380px] lg:w-[420px] shrink-0'}`}>
            <div className="p-5 border-b border-gray-100 shrink-0">
                <div className="flex justify-between items-center mb-5">
                    <h2 className="text-xl font-black text-gray-900 flex items-center gap-2">
                        <div className="p-2 bg-indigo-50 text-indigo-600 rounded-xl"><IconMail className="w-5 h-5" /></div>
                        {activeTab === 'inbox' ? t.inbox : t.sent}
                    </h2>
                    <button onClick={() => setIsComposeOpen(true)} className="p-2 bg-indigo-600 text-white rounded-xl shadow-lg shadow-indigo-100 hover:bg-indigo-700 transition-all hover:scale-110 active:scale-95">
                        <IconPlus className="w-5 h-5" />
                    </button>
                </div>

                <div className="flex bg-gray-100 p-1 rounded-2xl mb-4">
                    <button onClick={() => {setActiveTab('inbox'); setSelectedMsgId(null);}} className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-xl text-xs font-bold transition-all ${activeTab === 'inbox' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>
                        <IconInbox className="w-4 h-4" /> {t.inbox}
                    </button>
                    <button onClick={() => {setActiveTab('sent'); setSelectedMsgId(null);}} className={`flex-1 flex items-center justify-center gap-2 py-2 rounded-xl text-xs font-bold transition-all ${activeTab === 'sent' ? 'bg-white text-indigo-600 shadow-sm' : 'text-gray-500'}`}>
                        <IconSend className="w-4 h-4" /> {t.sent}
                    </button>
                </div>

                <div className="relative">
                    <input className="w-full pl-4 pr-10 py-3 bg-gray-50 border border-transparent rounded-2xl text-sm outline-none focus:bg-white focus:border-indigo-300 transition-all" placeholder={t.search} value={searchTerm} onChange={(e) => setSearchTerm(e.target.value)} />
                    <IconSearch className="w-4 h-4 text-gray-400 absolute right-3.5 top-3.5" />
                </div>
            </div>

            <div className="flex-grow overflow-y-auto custom-scrollbar bg-gray-50/20">
                {filteredMessages.length === 0 ? (
                    <div className="py-20 text-center flex flex-col items-center gap-3">
                        <div className="w-16 h-16 bg-gray-100 rounded-full flex items-center justify-center text-gray-300"><IconMail className="w-8 h-8" /></div>
                        <p className="text-gray-400 text-sm font-bold">{t.empty}</p>
                    </div>
                ) : (
                    <div className="divide-y divide-gray-50">
                        {filteredMessages.map(msg => {
                            const isUnread = activeTab === 'inbox' && !msg.readBy.includes(currentUser.id);
                            const isSelected = selectedMsgId === msg.id;

                            return (
                                <div 
                                    key={msg.id} 
                                    onClick={() => handleSelectMessage(msg)} 
                                    className={`group flex items-start gap-4 p-5 cursor-pointer transition-all relative border-r-4 ${isSelected ? 'bg-white border-indigo-600 shadow-sm z-10' : 'bg-transparent border-transparent hover:bg-white hover:border-gray-200'}`}
                                >
                                    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center text-white text-sm font-black shrink-0 shadow-sm transition-transform group-hover:scale-105 ${activeTab === 'inbox' ? 'bg-gradient-to-br from-indigo-500 to-indigo-700' : 'bg-gradient-to-br from-gray-400 to-gray-600'}`}>
                                        {activeTab === 'inbox' ? msg.senderName.charAt(0) : <IconSend className="w-5 h-5" />}
                                    </div>

                                    <div className="flex-grow min-w-0">
                                        <div className="flex justify-between items-center mb-1">
                                            <h4 className={`text-sm truncate ${isUnread ? 'font-black text-indigo-900' : 'font-bold text-gray-700'}`}>
                                                {activeTab === 'inbox' ? msg.senderName : msg.recipientNames.join(', ')}
                                            </h4>
                                            <span className="text-[10px] text-gray-400 whitespace-nowrap dir-ltr">
                                                {new Date(msg.createdAt).toLocaleDateString(lang === 'fa' ? 'fa-IR' : 'en-US')}
                                            </span>
                                        </div>
                                        <div className={`text-xs font-bold truncate mb-1 ${isUnread ? 'text-indigo-800' : 'text-gray-900'}`}>
                                            {msg.subject}
                                        </div>
                                        <div className="text-[11px] text-gray-500 truncate leading-relaxed">
                                            {msg.body.substring(0, 100)}
                                        </div>
                                        {msg.files && msg.files.length > 0 && (
                                            <div className="mt-2 flex items-center gap-1 text-[10px] text-indigo-500 font-bold">
                                                <IconPaperclip className="w-3 h-3" /> {msg.files.length} فایل پیوست
                                            </div>
                                        )}
                                    </div>

                                    {isUnread && (
                                        <div className="w-2.5 h-2.5 bg-indigo-600 rounded-full shadow-[0_0_8px_rgba(79,70,229,0.6)] animate-pulse mt-1"></div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>

        {/* --- Content Area (Message Details) --- */}
        <div className={`flex-grow flex flex-col bg-white overflow-hidden ${isMobile && !selectedMsgId ? 'hidden' : 'flex'}`}>
            {selectedMessage ? (
                <div className="flex flex-col h-full animate-fade-in">
                    {/* Detail Header */}
                    <div className="p-4 border-b border-gray-100 flex items-center justify-between bg-white shrink-0">
                        <div className="flex items-center gap-3">
                            {isMobile && (
                                <button onClick={() => setSelectedMsgId(null)} className="p-2 hover:bg-gray-100 rounded-full">
                                    <IconArrowRight className="w-5 h-5 ltr:rotate-180" />
                                </button>
                            )}
                            <div className="w-10 h-10 rounded-xl bg-gray-100 flex items-center justify-center font-black text-gray-400">{selectedMessage.senderName.charAt(0)}</div>
                            <div className="min-w-0">
                                <h3 className="font-black text-gray-900 text-sm md:text-base truncate">{selectedMessage.subject}</h3>
                                <p className="text-[10px] text-gray-500">{activeTab === 'inbox' ? t.from : t.to} <span className="font-bold text-gray-700">{activeTab === 'inbox' ? selectedMessage.senderName : selectedMessage.recipientNames.join(', ')}</span></p>
                            </div>
                        </div>
                        <div className="flex items-center gap-2">
                             <span className="hidden sm:inline text-[10px] font-bold text-gray-400 bg-gray-50 px-3 py-1.5 rounded-full border border-gray-100 dir-ltr">{new Date(selectedMessage.createdAt).toLocaleString(lang === 'fa' ? 'fa-IR' : 'en-US')}</span>
                             {isMaster && <button onClick={() => { if(confirm('حذف؟')) { deleteMessageFromCloud(selectedMessage.id); setSelectedMsgId(null); } }} className="p-2 text-gray-400 hover:text-red-500 hover:bg-red-50 rounded-xl transition-colors"><IconTrash className="w-5 h-5" /></button>}
                        </div>
                    </div>

                    {/* Detail Body */}
                    <div className="flex-grow overflow-y-auto p-8 custom-scrollbar">
                        <div className="max-w-3xl mx-auto">
                            <div className="bg-white p-8 rounded-3xl border border-gray-100 shadow-sm text-gray-800 text-sm md:text-base leading-loose whitespace-pre-wrap break-words min-h-[200px]">
                                {selectedMessage.body}
                            </div>

                            {selectedMessage.files && selectedMessage.files.length > 0 && (
                                <div className="mt-10">
                                    <h4 className="text-xs font-black text-gray-400 mb-4 uppercase tracking-widest flex items-center gap-2">
                                        <IconPaperclip className="w-4 h-4" /> {t.files}
                                    </h4>
                                    <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
                                        {selectedMessage.files.map((f, i) => (
                                            <a key={i} href={f.content} target="_blank" rel="noreferrer" className="flex items-center gap-4 p-4 bg-gray-50 rounded-2xl border border-gray-100 hover:border-indigo-300 hover:bg-indigo-50/50 transition-all group">
                                                <div className="p-2.5 bg-white rounded-xl shadow-sm text-indigo-600 group-hover:bg-indigo-600 group-hover:text-white transition-colors">
                                                    <IconFile className="w-5 h-5" />
                                                </div>
                                                <div className="min-w-0">
                                                    <div className="text-xs font-black text-gray-900 truncate">{f.name}</div>
                                                    <div className="text-[10px] text-gray-400 mt-0.5">{(f.size/1024/1024).toFixed(2)} MB</div>
                                                </div>
                                            </a>
                                        ))}
                                    </div>
                                </div>
                            )}
                        </div>
                    </div>

                    {/* Quick Reply Box */}
                    <div className="p-5 border-t border-gray-100 bg-gray-50/50 shrink-0">
                        <div className="max-w-3xl mx-auto flex items-center gap-4">
                            <div className="flex-grow relative">
                                <button 
                                    onClick={() => {
                                        setRecipientIds([selectedMessage.senderId]); 
                                        setSubject(`${lang==='fa'?'پاسخ به:':'Re:'} ${selectedMessage.subject}`); 
                                        setBody(`\n\n--- ${selectedMessage.senderName} ---\n> ${selectedMessage.body}`);
                                        setIsComposeOpen(true); 
                                    }}
                                    className="w-full bg-white border border-gray-200 rounded-2xl px-6 py-3 text-sm text-gray-400 font-bold hover:border-indigo-300 transition-all text-start flex items-center gap-3"
                                >
                                    <IconReply className="w-4 h-4 text-indigo-500" /> {t.reply}
                                </button>
                            </div>
                        </div>
                    </div>
                </div>
            ) : (
                <div className="flex-grow flex flex-col items-center justify-center text-gray-400 p-10 text-center animate-fade-in">
                    <div className="w-32 h-32 bg-indigo-50 rounded-full flex items-center justify-center mb-6">
                        <IconMail className="w-12 h-12 text-indigo-200" />
                    </div>
                    <h3 className="text-lg font-black text-gray-900 mb-2">{t.noSelect}</h3>
                    <p className="text-sm max-w-xs leading-relaxed">{activeTab === 'inbox' ? 'صندوق ورودی شما تماماً بررسی شده است.' : 'مکاتبات ارسال شده را می‌توانید از لیست سمت راست مدیریت کنید.'}</p>
                </div>
            )}
        </div>

        {/* --- Compose Full-Screen Modal --- */}
        {isComposeOpen && (
            <div className="fixed inset-0 z-[110] flex items-center justify-center p-4 bg-gray-900/60 backdrop-blur-md animate-fade-in" onClick={() => setIsComposeOpen(false)}>
                <div className="bg-white w-full max-w-2xl rounded-[40px] shadow-2xl flex flex-col max-h-[90vh] overflow-hidden" onClick={e => e.stopPropagation()}>
                    <div className="p-8 pb-4 border-b border-gray-50 flex justify-between items-center bg-white shrink-0">
                        <div>
                            <h3 className="font-black text-2xl text-gray-900 flex items-center gap-3">
                                <IconPlus className="w-6 h-6 text-indigo-600" /> {t.compose}
                            </h3>
                            <p className="text-xs text-gray-400 mt-1 font-bold">ارسال پیام داخلی امن به همکاران</p>
                        </div>
                        <button onClick={() => setIsComposeOpen(false)} className="p-3 hover:bg-red-50 hover:text-red-500 rounded-2xl transition-colors">✕</button>
                    </div>

                    <div className="p-8 flex-grow overflow-y-auto custom-scrollbar space-y-8">
                        <div>
                            <label className="text-[11px] font-black text-indigo-600 mb-2 block uppercase tracking-widest">{t.recipients}</label>
                            <div className="flex flex-wrap gap-2 p-3 bg-gray-50 border border-gray-100 rounded-3xl max-h-32 overflow-y-auto">
                                {personnel.filter(p => p.id !== currentUser.id).map(p => (
                                    <button 
                                        key={p.id} 
                                        onClick={() => setRecipientIds(prev => prev.includes(p.id) ? prev.filter(id => id !== p.id) : [...prev, p.id])} 
                                        className={`px-4 py-2 rounded-2xl text-xs font-black transition-all border shadow-sm ${recipientIds.includes(p.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-gray-500 border-gray-200 hover:border-indigo-300'}`}
                                    >
                                        {p.fullName}
                                    </button>
                                ))}
                            </div>
                        </div>

                        <div>
                            <label className="text-[11px] font-black text-indigo-600 mb-2 block uppercase tracking-widest">{t.subject}</label>
                            <input className="w-full py-4 px-6 text-sm font-black bg-gray-50 border border-transparent rounded-3xl outline-none focus:bg-white focus:border-indigo-300 transition-all" placeholder={t.subject} value={subject} onChange={e => setSubject(e.target.value)} />
                        </div>

                        <div>
                            <label className="text-[11px] font-black text-indigo-600 mb-2 block uppercase tracking-widest">{t.body}</label>
                            <textarea className="w-full h-60 py-4 px-6 text-sm text-gray-700 bg-gray-50 border border-transparent rounded-3xl outline-none focus:bg-white focus:border-indigo-300 transition-all resize-none" placeholder={t.writeHere} value={body} onChange={e => setBody(e.target.value)} />
                        </div>

                        {attachments.length > 0 && (
                            <div>
                                <label className="text-[11px] font-black text-indigo-600 mb-2 block uppercase tracking-widest">{t.files}</label>
                                <div className="grid grid-cols-2 gap-2">{attachments.map((f, i) => (
                                    <div key={i} className="flex items-center justify-between gap-3 bg-indigo-50 p-3 rounded-2xl border border-indigo-100 group animate-slide-in">
                                        <div className="flex items-center gap-2 min-w-0">
                                            <IconFile className="w-4 h-4 text-indigo-500 shrink-0" />
                                            <span className="text-[11px] font-black truncate text-indigo-900">{f.name}</span>
                                        </div>
                                        <div className="flex items-center gap-2">
                                            {f.status === 'uploading' && <span className="text-[10px] text-indigo-600 font-black">{Math.round(f.progress || 0)}%</span>}
                                            <button onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="text-red-400 hover:text-red-600">✕</button>
                                        </div>
                                    </div>
                                ))}</div>
                            </div>
                        )}
                    </div>

                    <div className="p-8 border-t border-gray-50 flex items-center justify-between bg-white shrink-0">
                        <button onClick={() => fileInputRef.current?.click()} className="flex items-center gap-2 text-indigo-600 font-black text-xs hover:bg-indigo-50 px-5 py-3 rounded-2xl transition-all">
                            <IconPaperclip className="w-5 h-5" /> {lang==='fa'?'افزودن فایل':'Add Attachment'}
                        </button>
                        <input type="file" ref={fileInputRef} className="hidden" onChange={handleFileSelect} multiple />

                        <div className="flex gap-3">
                            <button onClick={() => setIsComposeOpen(false)} className="px-6 py-3 text-xs font-black text-gray-400 hover:text-gray-600 transition-colors">{t.cancel}</button>
                            <button 
                                onClick={handleSendMessage} 
                                disabled={isSending || recipientIds.length === 0} 
                                className="bg-indigo-600 text-white px-10 py-3 rounded-2xl text-sm font-black shadow-xl shadow-indigo-100 hover:bg-indigo-700 hover:scale-105 active:scale-95 disabled:opacity-50 disabled:grayscale transition-all flex items-center gap-2"
                            >
                                {isSending ? <div className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></div> : <IconSend className="w-4 h-4" />}
                                {t.send}
                            </button>
                        </div>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

import React, { useState, useRef, useMemo, useEffect } from 'react';
import { InternalMessage, Personnel, AttachedFile } from '../types';
import { IconMail, IconSend, IconInbox, IconPaperclip, IconTrash, IconFile, IconReply, IconPlus, IconSearch, IconUsers, IconArrowRight, IconHistory } from './Icons';
import { sendInternalMessage, updateMessageInCloud, deleteMessageFromCloud, uploadFileWithProgress } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  messages: InternalMessage[];
  lang: Language;
}

export const InternalMessenger: React.FC<Props> = ({ currentUser, personnel, messages, lang }) => {
