                    <IconList className="w-6 h-6" />
                </div>
                <div>
                    <h2 className="text-xl font-black text-gray-900">{t.header}</h2>
                    <p className="text-sm text-gray-400 font-medium">{activeTab === 'active' ? t.activeTasks : t.archive}</p>
