export const saveCustomersBulkToCloud = async (customers: Customer[]) => {
    const batch = writeBatch(db);
    customers.forEach(c => {
        const ref = doc(db, "customers", c.id);
        batch.set(ref, sanitizeData(c));
    });
    await batch.commit();
};

