export const subscribeToSettings = (
    onConfig: (cfg: AppConfig) => void,
    onServices: (srv: ServiceOption[]) => void,
    onPersonnel: (ppl: Personnel[]) => void
) => {
    const unsubConfig = onSnapshot(doc(db, "settings", "appConfig"), (d) => {
        if (d.exists()) onConfig(d.data() as AppConfig);
    });
    const unsubServices = onSnapshot(doc(db, "settings", "services"), (d) => {
        if (d.exists()) onServices(d.data().list as ServiceOption[]);
    });
    const unsubPersonnel = onSnapshot(doc(db, "settings", "personnel"), (d) => {
        if (d.exists()) onPersonnel(d.data().list as Personnel[]);
    });
    return () => { unsubConfig(); unsubServices(); unsubPersonnel(); };
};

