// --- File Handling (Mocks) ---
export const uploadFileWithProgress = (
    file: File, 
    onProgress: (p: number) => void, 
    onSuccess: (url: string) => void, 
    onError: (err: any) => void
) => {
    // Mocking file upload progress
    let p = 0;
    const interval = setInterval(() => {
        p += 10;
        onProgress(p);
        if (p >= 100) {
            clearInterval(interval);
            // Simulating a data URL result
            const reader = new FileReader();
            reader.onloadend = () => onSuccess(reader.result as string);
            reader.onerror = onError;
            reader.readAsDataURL(file);
        }
    }, 100);
};

export const compressImage = async (file: File, maxWidth: number, quality: number = 0.7): Promise<string> => {
    return new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;
                if (width > maxWidth) {
                    height *= maxWidth / width;
                    width = maxWidth;
                }
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);
                resolve(canvas.toDataURL('image/jpeg', quality));
            };
            img.onerror = reject;
        };
        reader.onerror = reject;
    });
};

// --- Maintenance ---
export const backupSystemData = async (): Promise<boolean> => {
    try {
        const collections = ["tickets", "customers", "messages", "tasks", "meetings", "sales", "reports", "logs"];
        const backup: any = {};
        for (const col of collections) {
            const snap = await getDocs(collection(db, col));
            backup[col] = snap.docs.map(d => d.data());
        }
        const blob = new Blob([JSON.stringify(backup, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `backup-${new Date().toISOString().split('T')[0]}.json`;
        a.click();
        return true;
    } catch (e) {
        console.error(e);
        return false;
    }
};

export const clearSystemData = async (): Promise<boolean> => {
    try {
        const collections = ["tickets", "customers", "messages", "tasks", "meetings", "sales", "reports", "logs"];
        for (const colName of collections) {
            const q = query(collection(db, colName));
            const snap = await getDocs(q);
            const batch = writeBatch(db);
            snap.docs.forEach(d => batch.delete(d.ref));
            await batch.commit();
        }
        return true;
    } catch (e) {
        console.error(e);
        return false;
    }
};

