            </div>
            <button onClick={onLogout} className="w-full py-2 text-xs font-bold text-red-500 hover:bg-red-50 rounded-lg border border-red-100 transition-colors">خروج از سیستم</button>
        </div>

        <NavButton id="overview" label="داشبورد و تحلیل" icon={<IconChart className="w-5 h-5" />} />
        <NavButton id="messages" label="صندوق مکاتبات" icon={<IconMail className="w-5 h-5" />} />
