import React, { useState, useEffect, useMemo } from 'react';
import { UserGoalSet, GoalCategory, GoalTask, Personnel } from '../types';
import { IconTarget, IconCheck, IconPlus, IconTrash, IconSearch, IconArrowRight, IconStar, IconActivity, IconChart, IconHistory, IconList } from './Icons';
import { saveUserGoals, subscribeToAllGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const DEFAULT_CATEGORIES: GoalCategory[] = [
    { id: 'cat1', title: 'اهداف سلامتی', titleEn: 'Health Goals', color: 'emerald', tasks: [] },
    { id: 'cat2', title: 'اهداف شغلی', titleEn: 'Career Goals', color: 'indigo', tasks: [] },
    { id: 'cat3', title: 'اهداف مالی', titleEn: 'Financial Goals', color: 'amber', tasks: [] },
    { id: 'cat4', title: 'اهداف اجتماعی', titleEn: 'Social Goals', color: 'sky', tasks: [] },
    { id: 'cat5', title: 'اهداف شخصی', titleEn: 'Personal Goals', color: 'rose', tasks: [] },
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
  const [allGoals, setAllGoals] = useState<UserGoalSet[]>([]);
  const [currentGoalSet, setCurrentGoalSet] = useState<UserGoalSet | null>(null);
  const [filterUserId, setFilterUserId] = useState<string>(currentUser.id);
  const isMaster = currentUser.username === 'master';

  useEffect(() => {
    if (isMaster) {
        const unsub = subscribeToAllGoals(setAllGoals);
        return () => unsub();
    }
  }, [isMaster]);

  useEffect(() => {
    const unsub = subscribeToUserGoals(filterUserId, (data) => {
        if (data) setCurrentGoalSet(data);
        else {
            setCurrentGoalSet({
                id: filterUserId,
                userId: filterUserId,
                userName: personnel.find(p => p.id === filterUserId)?.fullName || 'User',
                updatedAt: new Date().toISOString(),
                categories: DEFAULT_CATEGORIES
            });
        }
    });
    return () => unsub();
  }, [filterUserId]);

  const handleUpdateTask = async (catId: string, taskId: string, completed: boolean) => {
    if (!currentGoalSet || (currentUser.id !== filterUserId && !isMaster)) return;
    const updatedCategories = currentGoalSet.categories.map(cat => {
        if (cat.id === catId) {
            return { ...cat, tasks: cat.tasks.map(t => t.id === taskId ? { ...t, isCompleted: completed } : t) };
        }
        return cat;
    });
    const updatedSet = { ...currentGoalSet, categories: updatedCategories, updatedAt: new Date().toISOString() };
    setCurrentGoalSet(updatedSet);
    await saveUserGoals(updatedSet);
  };

  const handleAddTask = async (catId: string, text: string) => {
    if (!text.trim() || !currentGoalSet) return;
    const updatedCategories = currentGoalSet.categories.map(cat => {
        if (cat.id === catId) {
            const newTask: GoalTask = { id: `task-${Date.now()}`, text, isCompleted: false };
            return { ...cat, tasks: [...cat.tasks, newTask] };
        }
        return cat;
    });
    const updatedSet = { ...currentGoalSet, categories: updatedCategories, updatedAt: new Date().toISOString() };
    setCurrentGoalSet(updatedSet);
    await saveUserGoals(updatedSet);
  };

  const handleDeleteTask = async (catId: string, taskId: string) => {
    if (!currentGoalSet || !window.confirm('حذف شود؟')) return;
    const updatedCategories = currentGoalSet.categories.map(cat => {
        if (cat.id === catId) {
            return { ...cat, tasks: cat.tasks.filter(t => t.id !== taskId) };
        }
        return cat;
    });
    const updatedSet = { ...currentGoalSet, categories: updatedCategories, updatedAt: new Date().toISOString() };
    setCurrentGoalSet(updatedSet);
    await saveUserGoals(updatedSet);
  };

  const stats = useMemo(() => {
    if (!currentGoalSet) return { total: 0, done: 0, progress: 0 };
    const allTasks = currentGoalSet.categories.flatMap(c => c.tasks);
    const total = allTasks.length;
    const done = allTasks.filter(t => t.isCompleted).length;
    return { total, done, progress: total ? Math.round((done / total) * 100) : 0 };
  }, [currentGoalSet]);

  if (!currentGoalSet) return <div className="p-20 text-center text-gray-400">در حال بارگذاری اهداف...</div>;

  return (
    <div className="space-y-8 animate-fade-in pb-10">
      {/* --- DASHBOARD HEADER --- */}
      <div className="bg-white rounded-[2.5rem] border border-gray-100 shadow-xl p-8 ring-1 ring-black/5">
        <div className="flex flex-col xl:flex-row gap-8 items-stretch">

          {/* 1. Title & Date */}
          <div className="xl:w-1/5 flex flex-col justify-center border-l border-gray-100 pl-6">
            <div className="flex items-center gap-3 mb-2">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-100"><IconTarget className="w-6 h-6" /></div>
                <h2 className="text-2xl font-black text-gray-900 tracking-tight">SMART<br/>GOALS</h2>
            </div>
            <p className="text-sm font-black text-gray-400 mt-2 dir-ltr text-right">{new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })}</p>

            {isMaster && (
                <div className="mt-6">
                    <label className="text-[10px] font-black text-indigo-600 block mb-2 uppercase tracking-widest">مشاهده اهدافِ:</label>
                    <select 
                        className="w-full bg-gray-50 border-none rounded-xl text-xs font-black p-3 outline-none ring-1 ring-gray-200 focus:ring-indigo-500 transition-all"
                        value={filterUserId}
                        onChange={e => setFilterUserId(e.target.value)}
                    >
                        {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                    </select>
                </div>
            )}
          </div>

          {/* 2. Overall Completion (Gauge Style) */}
          <div className="xl:w-1/5 flex flex-col items-center justify-center border-l border-gray-100 px-6">
            <h4 className="text-[11px] font-black text-gray-400 mb-6 uppercase tracking-widest text-center">OVERALL TASK COMPLETION</h4>
            <div className="relative w-32 h-32 flex items-center justify-center">
                <svg className="w-full h-full transform -rotate-90">
                    <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="10" fill="transparent" className="text-gray-100" />
                    <circle cx="64" cy="64" r="58" stroke="currentColor" strokeWidth="10" fill="transparent" strokeDasharray={364.4} strokeDashoffset={364.4 - (364.4 * stats.progress) / 100} className="text-indigo-600 transition-all duration-1000" />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-2xl font-black text-gray-900">{stats.progress}%</span>
                    <span className="text-[9px] font-black text-gray-400 uppercase">DONE</span>
                </div>
            </div>
          </div>

          {/* 3. Done vs To-Do Chart (Simplified Visual) */}
          <div className="xl:w-1/4 flex flex-col justify-center border-l border-gray-100 px-6">
            <h4 className="text-[11px] font-black text-gray-400 mb-4 uppercase tracking-widest">DONE VS. TO-DO BY GOALS</h4>
            <div className="space-y-3">
                {currentGoalSet.categories.map(cat => {
                    const done = cat.tasks.filter(t => t.isCompleted).length;
                    const total = cat.tasks.length;
                    const p = total ? (done / total) * 100 : 0;
                    return (
                        <div key={cat.id} className="space-y-1">
                            <div className="flex justify-between text-[9px] font-black text-gray-500 uppercase">
                                <span>{lang === 'fa' ? cat.title : cat.titleEn}</span>
                                <span>{done}/{total}</span>
                            </div>
                            <div className="h-2 bg-gray-100 rounded-full overflow-hidden flex">
                                <div className={`h-full bg-${cat.color}-500 transition-all duration-700`} style={{ width: `${p}%` }}></div>
                            </div>
                        </div>
                    )
                })}
            </div>
          </div>

          {/* 4. SMART Checklist */}
          <div className="xl:w-1/4 flex flex-col justify-center bg-gray-50/50 p-6 rounded-3xl border border-gray-100">
            <h4 className="text-[11px] font-black text-gray-900 mb-4 uppercase tracking-widest text-center border-b border-gray-200 pb-2">SMART GOALS CHECK</h4>
            <div className="space-y-2.5">
                {[
                    { l: 'S', t: 'SPECIFIC', d: 'Clear and focused goals.' },
                    { l: 'M', t: 'MEASURABLE', d: 'Trackable progress steps.' },
                    { l: 'A', t: 'ACHIEVABLE', d: 'Realistic and doable.' },
                    { l: 'R', t: 'RELEVANT', d: 'Aligned with purpose.' },
                    { l: 'T', t: 'TIME-BOUND', d: 'Set a deadline.' }
                ].map((item, i) => (
                    <div key={i} className="flex items-center gap-3">
                        <div className="w-5 h-5 rounded bg-white border border-gray-200 flex items-center justify-center"><IconCheck className="w-3 h-3 text-indigo-600" /></div>
                        <div className="flex gap-2 items-baseline">
                            <span className="text-xs font-black text-gray-900">{item.l}</span>
                            <span className="text-[10px] font-bold text-gray-400 leading-none">{item.d}</span>
                        </div>
                    </div>
                ))}
            </div>
          </div>
        </div>
      </div>

      {/* --- GOALS MAIN BODY (5 COLUMNS) --- */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6 items-start">
        {currentGoalSet.categories.map((cat) => {
            const done = cat.tasks.filter(t => t.isCompleted).length;
            const total = cat.tasks.length;
            const progress = total ? Math.round((done / total) * 100) : 0;
            const isReadonly = currentUser.id !== filterUserId && !isMaster;

            return (
                <div key={cat.id} className="bg-white rounded-[2rem] border border-gray-100 shadow-lg overflow-hidden flex flex-col h-full min-h-[500px]">
                    {/* Header */}
                    <div className={`p-5 bg-${cat.color}-500 text-white text-center shrink-0`}>
                        <h3 className="font-black text-sm uppercase tracking-widest">{lang === 'fa' ? cat.title : cat.titleEn}</h3>
                    </div>

                    {/* Summary Table */}
                    <div className="grid grid-cols-3 border-b border-gray-50 text-center bg-gray-50/30">
                        <div className="p-3 border-l border-gray-50">
                            <div className="text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tighter">DONE</div>
                            <div className="text-sm font-black text-gray-800">{done}</div>
                        </div>
                        <div className="p-3 border-l border-gray-50">
                            <div className="text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tighter">TOTAL</div>
                            <div className="text-sm font-black text-gray-800">{total}</div>
                        </div>
                        <div className="p-3">
                            <div className="text-[10px] font-black text-gray-400 uppercase mb-1 tracking-tighter">PROGRESS</div>
                            <div className={`text-sm font-black text-${cat.color}-600`}>{progress}%</div>
                        </div>
                    </div>

                    {/* Progress Bar */}
                    <div className="h-1.5 w-full bg-gray-100 shrink-0">
                        <div className={`h-full bg-${cat.color}-500 transition-all duration-700`} style={{ width: `${progress}%` }}></div>
                    </div>

                    {/* Tasks List */}
                    <div className="flex-grow p-5 space-y-3 overflow-y-auto custom-scrollbar bg-white">
                        <h4 className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                            <IconList className="w-3 h-3" /> TASKS
                        </h4>
                        {cat.tasks.map((task, idx) => (
                            <div key={task.id} className="flex items-start gap-3 group animate-slide-in">
                                <span className="text-[10px] font-black text-gray-300 mt-1">{idx + 1}</span>
                                <div 
                                    onClick={() => !isReadonly && handleUpdateTask(cat.id, task.id, !task.isCompleted)}
                                    className={`flex-grow cursor-pointer flex items-start gap-3 p-2 rounded-xl transition-all ${task.isCompleted ? 'opacity-40' : 'hover:bg-gray-50'}`}
                                >
                                    <div className={`w-5 h-5 rounded-lg border-2 shrink-0 flex items-center justify-center transition-all ${task.isCompleted ? `bg-${cat.color}-500 border-${cat.color}-500 text-white shadow-sm` : 'border-gray-200 bg-white'}`}>
                                        {task.isCompleted && <IconCheck className="w-3 h-3" />}
                                    </div>
                                    <span className={`text-xs font-bold leading-relaxed break-words ${task.isCompleted ? 'line-through text-gray-500' : 'text-gray-700'}`}>
                                        {task.text}
                                    </span>
                                </div>
                                {!isReadonly && (
                                    <button onClick={() => handleDeleteTask(cat.id, task.id)} className="opacity-0 group-hover:opacity-100 p-1 text-red-300 hover:text-red-500 transition-all">
                                        <IconTrash className="w-3.5 h-3.5" />
                                    </button>
                                )}
                            </div>
                        ))}

                        {/* Empty State */}
                        {cat.tasks.length === 0 && (
                            <div className="py-10 text-center opacity-20">
                                <IconTarget className={`w-8 h-8 mx-auto mb-2 text-${cat.color}-500`} />
                                <p className="text-[10px] font-black uppercase">No tasks yet</p>
                            </div>
                        )}
                    </div>

                    {/* Quick Add */}
                    {!isReadonly && (
                        <div className="p-4 bg-gray-50 border-t border-gray-100 shrink-0">
                            <input 
                                className="w-full bg-white border border-gray-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                                placeholder="افزودن هدف جدید..."
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddTask(cat.id, (e.target as HTMLInputElement).value);
                                        (e.target as HTMLInputElement).value = '';
                                    }
                                }}
                            />
                        </div>
                    )}
                </div>
            )
        })}
      </div>
    </div>
  );
};

import React, { useState, useEffect, useMemo } from 'react';
import { UserGoalSet, GoalCategory, GoalTask, Personnel } from '../types';
import { IconTarget, IconCheck, IconPlus, IconTrash, IconList } from './Icons';
import { saveUserGoals, subscribeToAllGoals, subscribeToUserGoals } from '../services/firebaseService';
import { Language } from '../App';

interface Props {
  currentUser: Personnel;
  personnel: Personnel[];
  lang: Language;
}

const DEFAULT_CATEGORIES: GoalCategory[] = [
    { id: 'cat1', title: 'اهداف سلامتی', titleEn: 'Health Goals', color: 'emerald', tasks: [] },
    { id: 'cat2', title: 'اهداف شغلی', titleEn: 'Career Goals', color: 'indigo', tasks: [] },
    { id: 'cat3', title: 'اهداف مالی', titleEn: 'Financial Goals', color: 'amber', tasks: [] },
    { id: 'cat4', title: 'اهداف اجتماعی', titleEn: 'Social Goals', color: 'sky', tasks: [] },
    { id: 'cat5', title: 'اهداف شخصی', titleEn: 'Personal Goals', color: 'rose', tasks: [] },
];

export const GoalTracker: React.FC<Props> = ({ currentUser, personnel, lang }) => {
  const [currentGoalSet, setCurrentGoalSet] = useState<UserGoalSet | null>(null);
  const [filterUserId, setFilterUserId] = useState<string>(currentUser.id);
  const isMaster = currentUser.username === 'master';

  // Subscribe to specific user's goals
  useEffect(() => {
    const unsub = subscribeToUserGoals(filterUserId, (data) => {
        if (data) {
            setCurrentGoalSet(data);
        } else {
            // Initialize if first time
            setCurrentGoalSet({
                id: filterUserId,
                userId: filterUserId,
                userName: personnel.find(p => p.id === filterUserId)?.fullName || 'User',
                updatedAt: new Date().toISOString(),
                categories: JSON.parse(JSON.stringify(DEFAULT_CATEGORIES))
            });
        }
    });
    return () => unsub();
  }, [filterUserId, personnel]);

  const handleUpdateTask = async (catId: string, taskId: string, completed: boolean) => {
    if (!currentGoalSet) return;
    // Check permission: owner or master
    if (currentUser.id !== filterUserId && !isMaster) return;

    const updatedCategories = currentGoalSet.categories.map(cat => {
        if (cat.id === catId) {
            return { ...cat, tasks: cat.tasks.map(t => t.id === taskId ? { ...t, isCompleted: completed } : t) };
        }
        return cat;
    });
    const updatedSet = { ...currentGoalSet, categories: updatedCategories, updatedAt: new Date().toISOString() };
    setCurrentGoalSet(updatedSet);
    await saveUserGoals(updatedSet);
  };

  const handleAddTask = async (catId: string, text: string) => {
    if (!text.trim() || !currentGoalSet) return;
    if (currentUser.id !== filterUserId && !isMaster) return;

    const updatedCategories = currentGoalSet.categories.map(cat => {
        if (cat.id === catId) {
            const newTask: GoalTask = { id: `gt-${Date.now()}`, text, isCompleted: false };
            return { ...cat, tasks: [...cat.tasks, newTask] };
        }
        return cat;
    });
    const updatedSet = { ...currentGoalSet, categories: updatedCategories, updatedAt: new Date().toISOString() };
    setCurrentGoalSet(updatedSet);
    await saveUserGoals(updatedSet);
  };

  const handleDeleteTask = async (catId: string, taskId: string) => {
    if (!currentGoalSet || !window.confirm(lang === 'fa' ? 'این مورد حذف شود؟' : 'Delete this task?')) return;
    if (currentUser.id !== filterUserId && !isMaster) return;

    const updatedCategories = currentGoalSet.categories.map(cat => {
        if (cat.id === catId) {
            return { ...cat, tasks: cat.tasks.filter(t => t.id !== taskId) };
        }
        return cat;
    });
    const updatedSet = { ...currentGoalSet, categories: updatedCategories, updatedAt: new Date().toISOString() };
    setCurrentGoalSet(updatedSet);
    await saveUserGoals(updatedSet);
  };

  const stats = useMemo(() => {
    if (!currentGoalSet) return { total: 0, done: 0, progress: 0 };
    const allTasks = currentGoalSet.categories.flatMap(c => c.tasks);
    const total = allTasks.length;
    const done = allTasks.filter(t => t.isCompleted).length;
    return { total, done, progress: total ? Math.round((done / total) * 100) : 0 };
  }, [currentGoalSet]);

  const smartChecklist = [
    { l: 'S', t: 'SPECIFIC', d: lang === 'fa' ? 'اهداف دقیق و متمرکز' : 'Clear and focused goals.' },
    { l: 'M', t: 'MEASURABLE', d: lang === 'fa' ? 'قابل اندازه‌گیری و رصد' : 'Trackable progress steps.' },
    { l: 'A', t: 'ACHIEVABLE', d: lang === 'fa' ? 'واقع‌بینانه و قابل دستیابی' : 'Realistic and doable.' },
    { l: 'R', t: 'RELEVANT', d: lang === 'fa' ? 'مرتبط با رسالت فردی/شغلی' : 'Aligned with purpose.' },
    { l: 'T', t: 'TIME-BOUND', d: lang === 'fa' ? 'دارای بازه زمانی مشخص' : 'Set a deadline.' }
  ];

  if (!currentGoalSet) return <div className="p-20 text-center text-gray-400">در حال بارگذاری اهداف...</div>;

  return (
    <div className="space-y-8 animate-fade-in pb-12">
      {/* --- DASHBOARD HEADER --- */}
      <div className="bg-white rounded-[2rem] border border-gray-100 shadow-xl p-8 ring-1 ring-black/5">
        <div className="grid grid-cols-1 xl:grid-cols-4 gap-8 items-center">

          {/* 1. Title & Date & User Picker */}
          <div className="xl:border-l border-gray-100 pl-6 h-full flex flex-col justify-center">
            <div className="flex items-center gap-3 mb-2">
                <div className="p-3 bg-indigo-600 text-white rounded-2xl shadow-lg shadow-indigo-100">
                    <IconTarget className="w-6 h-6" />
                </div>
                <h2 className="text-2xl font-black text-gray-900 leading-tight">SMART<br/>GOALS</h2>
            </div>
            <p className="text-sm font-black text-gray-400 mt-2 dir-ltr">
                {new Date().toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })}
            </p>

            {isMaster && (
                <div className="mt-4 pt-4 border-t border-gray-50">
                    <label className="text-[10px] font-black text-indigo-600 block mb-2 uppercase tracking-widest">مشاهده اهدافِ:</label>
                    <select 
                        className="w-full bg-gray-50 border-none rounded-xl text-xs font-black p-3 outline-none ring-1 ring-gray-200 focus:ring-indigo-500 transition-all"
                        value={filterUserId}
                        onChange={e => setFilterUserId(e.target.value)}
                    >
                        {personnel.map(p => <option key={p.id} value={p.id}>{p.fullName}</option>)}
                    </select>
                </div>
            )}
          </div>

          {/* 2. Overall Completion Gauge */}
          <div className="xl:border-l border-gray-100 px-6 flex flex-col items-center justify-center">
            <h4 className="text-[10px] font-black text-gray-400 mb-4 uppercase tracking-widest text-center">OVERALL COMPLETION</h4>
            <div className="relative w-28 h-28 flex items-center justify-center">
                <svg className="w-full h-full transform -rotate-90">
                    <circle cx="56" cy="56" r="50" stroke="currentColor" strokeWidth="8" fill="transparent" className="text-gray-100" />
                    <circle cx="56" cy="56" r="50" stroke="currentColor" strokeWidth="8" fill="transparent" strokeDasharray={314.15} strokeDashoffset={314.15 - (314.15 * stats.progress) / 100} className="text-indigo-600 transition-all duration-1000" />
                </svg>
                <div className="absolute inset-0 flex flex-col items-center justify-center">
                    <span className="text-xl font-black text-gray-900">{stats.progress}%</span>
                    <span className="text-[8px] font-black text-gray-400 uppercase">DONE</span>
                </div>
            </div>
          </div>

          {/* 3. Bar Stats Visual */}
          <div className="xl:border-l border-gray-100 px-6 flex flex-col justify-center">
            <h4 className="text-[10px] font-black text-gray-400 mb-4 uppercase tracking-widest">DONE VS. TO-DO BY GOALS</h4>
            <div className="space-y-2.5">
                {currentGoalSet.categories.map(cat => {
                    const done = cat.tasks.filter(t => t.isCompleted).length;
                    const total = cat.tasks.length;
                    const p = total ? (done / total) * 100 : 0;
                    return (
                        <div key={cat.id} className="space-y-1">
                            <div className="flex justify-between text-[8px] font-black text-gray-500 uppercase">
                                <span>{lang === 'fa' ? cat.title : cat.titleEn}</span>
                                <span>{done}/{total}</span>
                            </div>
                            <div className="h-1.5 bg-gray-100 rounded-full overflow-hidden">
                                <div className={`h-full bg-${cat.color}-500 transition-all duration-700`} style={{ width: `${p}%` }}></div>
                            </div>
                        </div>
                    )
                })}
            </div>
          </div>

          {/* 4. SMART Checklist */}
          <div className="bg-gray-50/50 p-6 rounded-2xl border border-gray-100 flex flex-col justify-center">
            <h4 className="text-[10px] font-black text-gray-900 mb-3 uppercase tracking-widest text-center border-b border-gray-200 pb-2">SMART GOALS CHECK</h4>
            <div className="space-y-1.5">
                {smartChecklist.map((item, i) => (
                    <div key={i} className="flex items-center gap-3">
                        <div className="w-4 h-4 rounded bg-white border border-gray-200 flex items-center justify-center">
                            <IconCheck className="w-2.5 h-2.5 text-indigo-600" />
                        </div>
                        <div className="flex gap-1.5 items-center">
                            <span className="text-[10px] font-black text-gray-900">{item.l}</span>
                            <span className="text-[9px] font-bold text-gray-400 leading-none">{item.d}</span>
                        </div>
                    </div>
                ))}
            </div>
          </div>

        </div>
      </div>

      {/* --- GOALS MAIN BODY (5 COLUMNS) --- */}
      <div className="grid grid-cols-1 md:grid-cols-3 xl:grid-cols-5 gap-6 items-start">
        {currentGoalSet.categories.map((cat) => {
            const done = cat.tasks.filter(t => t.isCompleted).length;
            const total = cat.tasks.length;
            const progress = total ? Math.round((done / total) * 100) : 0;
            const isReadonly = currentUser.id !== filterUserId && !isMaster;

            return (
                <div key={cat.id} className="bg-white rounded-[2rem] border border-gray-100 shadow-lg overflow-hidden flex flex-col h-full min-h-[550px] transition-all hover:shadow-xl">
                    {/* Header Strip */}
                    <div className={`p-5 bg-${cat.color}-500 text-white text-center shrink-0`}>
                        <h3 className="font-black text-sm uppercase tracking-widest">
                            {lang === 'fa' ? cat.title : cat.titleEn}
                        </h3>
                    </div>

                    {/* Summary Stats Table */}
                    <div className="grid grid-cols-3 border-b border-gray-50 text-center bg-gray-50/30">
                        <div className="p-3 border-l border-gray-50">
                            <div className="text-[9px] font-black text-gray-400 uppercase mb-1">DONE</div>
                            <div className="text-sm font-black text-gray-800">{done}</div>
                        </div>
                        <div className="p-3 border-l border-gray-50">
                            <div className="text-[9px] font-black text-gray-400 uppercase mb-1">TOTAL</div>
                            <div className="text-sm font-black text-gray-800">{total}</div>
                        </div>
                        <div className="p-3">
                            <div className="text-[9px] font-black text-gray-400 uppercase mb-1">PROGRESS</div>
                            <div className={`text-sm font-black text-${cat.color}-600`}>{progress}%</div>
                        </div>
                    </div>

                    {/* Linear Progress Bar */}
                    <div className="h-1.5 w-full bg-gray-100 shrink-0">
                        <div className={`h-full bg-${cat.color}-500 transition-all duration-1000 ease-out`} style={{ width: `${progress}%` }}></div>
                    </div>

                    {/* Tasks Numbered List */}
                    <div className="flex-grow p-5 space-y-3 overflow-y-auto custom-scrollbar bg-white">
                        <h4 className="text-[9px] font-black text-gray-400 uppercase tracking-widest mb-4 flex items-center gap-2">
                            <IconList className="w-3 h-3" /> TASKS
                        </h4>
                        <div className="space-y-1">
                            {cat.tasks.map((task, idx) => (
                                <div key={task.id} className="flex items-start gap-2 group animate-slide-in">
                                    <span className="text-[10px] font-black text-gray-300 mt-2.5 w-4 text-center">{idx + 1}</span>
                                    <div 
                                        onClick={() => !isReadonly && handleUpdateTask(cat.id, task.id, !task.isCompleted)}
                                        className={`flex-grow cursor-pointer flex items-start gap-3 p-2 rounded-xl transition-all ${task.isCompleted ? 'opacity-40' : 'hover:bg-gray-50'}`}
                                    >
                                        <div className={`w-5 h-5 rounded-lg border-2 shrink-0 flex items-center justify-center transition-all ${task.isCompleted ? `bg-${cat.color}-500 border-${cat.color}-500 text-white shadow-sm` : 'border-gray-200 bg-white group-hover:border-indigo-300'}`}>
                                            {task.isCompleted && <IconCheck className="w-3 h-3" />}
                                        </div>
                                        <span className={`text-xs font-bold leading-relaxed break-words pt-0.5 ${task.isCompleted ? 'line-through text-gray-500' : 'text-gray-700'}`}>
                                            {task.text}
                                        </span>
                                    </div>
                                    {!isReadonly && (
                                        <button onClick={() => handleDeleteTask(cat.id, task.id)} className="opacity-0 group-hover:opacity-100 p-2 text-red-300 hover:text-red-500 transition-all">
                                            <IconTrash className="w-3.5 h-3.5" />
                                        </button>
                                    )}
                                </div>
                            ))}
                        </div>

                        {/* Empty Placeholder */}
                        {cat.tasks.length === 0 && (
                            <div className="py-20 text-center opacity-20">
                                <IconTarget className={`w-8 h-8 mx-auto mb-2 text-${cat.color}-500`} />
                                <p className="text-[9px] font-black uppercase">No goals added</p>
                            </div>
                        )}
                    </div>

                    {/* Quick Add Bar */}
                    {!isReadonly && (
                        <div className="p-4 bg-gray-50 border-t border-gray-100 shrink-0">
                            <input 
                                className="w-full bg-white border border-gray-200 rounded-xl px-4 py-2.5 text-xs font-bold outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                                placeholder={lang === 'fa' ? 'افزودن تسک جدید...' : 'Add new task...'}
                                onKeyDown={(e) => {
                                    if (e.key === 'Enter') {
                                        handleAddTask(cat.id, (e.target as HTMLInputElement).value);
                                        (e.target as HTMLInputElement).value = '';
                                    }
                                }}
                            />
                        </div>
                    )}
                </div>
            )
        })}
      </div>
    </div>
  );
};

import React, { useState } from 'react';
import { 
    Ticket, ServiceOption, Personnel, Customer, AppConfig, 
    InternalMessage, Task, Meeting, KPI, ViewState 
} from '../types';
import { 
    IconLayout, IconBriefcase, IconUsers, IconSettings, IconMoney, 
    IconMail, IconList, IconCalendarClock, IconDatabase, IconChart, 
    IconTarget, IconStar, IconShield, IconClipboard 
} from './Icons';
import { ServiceManager } from './ServiceManager';
import { PersonnelManager } from './PersonnelManager';
import { CustomerManager } from './CustomerManager';
import { SettingsManager } from './SettingsManager';
import { InternalMessenger } from './InternalMessenger';
import { TaskManager } from './TaskManager';
import { MeetingCalendar } from './MeetingCalendar';
import { PerformanceReports } from './PerformanceReports';
import { KPIManager } from './KPIManager';
import { SalesDashboard } from './SalesDashboard';
import { ReportManager } from './ReportManager';
import { GoalTracker } from './GoalTracker';
import { Language } from '../App';

interface Props {
  lang: Language;
  currentUser: Personnel;
  tickets: Ticket[];
  services: ServiceOption[];
  personnel: Personnel[];
  customers: Customer[];
  messages: InternalMessage[];
  tasks: Task[];
  meetings: Meeting[];
  kpis: KPI[];
  config: AppConfig;
  onCreateTicket: (t: Ticket | Ticket[]) => Promise<void>;
  onUpdateTicket: (id: string, updates: Partial<Ticket>, actor: string, note?: string) => Promise<void>;
  onDeleteTicket: (id: string) => Promise<void>;
  onUpdateServices: (s: ServiceOption[]) => Promise<void>;
  onUpdatePersonnel: (p: Personnel[]) => Promise<void>;
  onUpdateCustomers: (c: Customer[]) => Promise<void>;
  onEditCustomer: (id: string, u: Partial<Customer>) => Promise<void>;
  onDeleteCustomer: (id: string) => Promise<void>;
  onUpdateConfig: (cfg: AppConfig) => Promise<void>;
  onLogout: () => void;
}

export const AdminDashboard: React.FC<Props> = ({ 
  lang, currentUser, tickets, services, personnel, customers, 
  messages, tasks, meetings, kpis, config,
  onUpdateServices, onUpdatePersonnel, onUpdateCustomers, 
  onEditCustomer, onDeleteCustomer, onUpdateConfig, onLogout 
}) => {
  const [activeTab, setActiveTab] = useState<'overview' | 'projects' | 'services' | 'personnel' | 'customers' | 'settings' | 'financial' | 'messages' | 'tasks' | 'meetings' | 'reports' | 'kpi' | 'sales' | 'staff_reports' | 'goals'>('overview');

  const isAdmin = currentUser.roles.includes('مدیر') || currentUser.username === 'master';

  const NavButton = ({ id, label, icon }: { id: any, label: string, icon: any }) => (
    <button 
      onClick={() => setActiveTab(id)}
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === id ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-100'}`}
    >
      {icon}
      <span className="font-medium text-sm">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col md:flex-row gap-6 min-h-[calc(100vh-100px)]">
      {/* Sidebar */}
      <div className="w-full md:w-72 shrink-0 space-y-2">
        <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm mb-4">
            <div className="flex items-center gap-3 mb-4">
                <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold overflow-hidden">
                    {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full object-cover" /> : currentUser.fullName.charAt(0)}
                </div>
                <div className="overflow-hidden">
                    <div className="font-bold text-gray-900 truncate">{currentUser.fullName}</div>
                    <div className="text-xs text-gray-500 truncate">{currentUser.roles.join(', ')}</div>
                </div>
            </div>
            <button onClick={onLogout} className="w-full py-2 text-xs font-bold text-red-500 hover:bg-red-50 rounded-lg border border-red-100 transition-colors">خروج از سیستم</button>
        </div>

        <NavButton id="overview" label="داشبورد و تحلیل" icon={<IconChart className="w-5 h-5" />} />
        <NavButton id="messages" label="صندوق مکاتبات" icon={<IconMail className="w-5 h-5" />} />
        <NavButton id="tasks" label="امور روزانه" icon={<IconList className="w-5 h-5" />} />
        <NavButton id="goals" label="ردیاب اهداف (Goal Tracker)" icon={<IconTarget className="w-5 h-5" />} />
        <NavButton id="meetings" label="تقویم جلسات" icon={<IconCalendarClock className="w-5 h-5" />} />
        <NavButton id="staff_reports" label="گزارش عملکرد" icon={<IconClipboard className="w-5 h-5" />} />
        <NavButton id="sales" label="فروش و کمیسیون" icon={<IconMoney className="w-5 h-5" />} />

        {isAdmin && (
            <>
                <div className="h-px bg-gray-200 my-4 mx-4"></div>
                <NavButton id="customers" label="بانک مشتریان" icon={<IconUsers className="w-5 h-5" />} />
                <NavButton id="services" label="تعرفه‌ها و خدمات" icon={<IconBriefcase className="w-5 h-5" />} />
                <NavButton id="personnel" label="مدیریت پرسنل" icon={<IconShield className="w-5 h-5" />} />
                <NavButton id="kpi" label="مدیریت KPI" icon={<IconTarget className="w-5 h-5" />} />
                <NavButton id="reports" label="گزارشات سیستمی" icon={<IconDatabase className="w-5 h-5" />} />
                <NavButton id="settings" label="تنظیمات سیستم" icon={<IconSettings className="w-5 h-5" />} />
            </>
        )}
      </div>

      {/* Main Area */}
      <div className="flex-grow">
        {activeTab === 'overview' && <PerformanceReports personnel={personnel} tickets={tickets} tasks={tasks} lang={lang} />}
        {activeTab === 'messages' && <InternalMessenger currentUser={currentUser} personnel={personnel} messages={messages} lang={lang} />}
        {activeTab === 'tasks' && <TaskManager currentUser={currentUser} personnel={personnel} tasks={tasks} lang={lang} />}
        {activeTab === 'goals' && <GoalTracker currentUser={currentUser} personnel={personnel} lang={lang} />}
        {activeTab === 'meetings' && <MeetingCalendar meetings={meetings} currentUser={currentUser} personnel={personnel} lang={lang} />}
        {activeTab === 'staff_reports' && <ReportManager currentUser={currentUser} personnel={personnel} lang={lang} config={config} />}
        {activeTab === 'sales' && <SalesDashboard currentUser={currentUser} personnel={personnel} services={services} onUpdatePersonnel={onUpdatePersonnel} onUpdateServices={onUpdateServices} lang={lang} />}
        {activeTab === 'customers' && <CustomerManager customers={customers} currentUser={currentUser} onUpdate={onUpdateCustomers} onEdit={onEditCustomer} onDelete={onDeleteCustomer} lang={lang} />}
        {activeTab === 'services' && <ServiceManager services={services} onUpdate={onUpdateServices} lang={lang} />}
        {activeTab === 'personnel' && <PersonnelManager personnel={personnel} config={config} onUpdate={onUpdatePersonnel} onUpdateConfig={onUpdateConfig} lang={lang} />}
        {activeTab === 'kpi' && <KPIManager kpis={kpis} personnel={personnel} lang={lang} />}
        {activeTab === 'settings' && <SettingsManager config={config} onUpdate={onUpdateConfig} isMaster={currentUser.username === 'master'} />}
        {activeTab === 'reports' && <div className="p-10 text-center text-gray-400 bg-white rounded-2xl border border-dashed">بخش گزارشات پیشرفته در حال بروزرسانی است.</div>}
      </div>
    </div>
  );
};

