// Helper for sanitizing data for Firestore
export const sanitizeData = (data: any): any => {
    return JSON.parse(JSON.stringify(data));
};

// --- LOGGING ---
export const logSystemAction = async (actionType: string, category: string, description: string, actorName: string, actorId: string) => {
    const log: SystemLog = {
        id: `log-${Date.now()}`,
        actionType,
        category,
        description,
        actorName,
        actorId,
        timestamp: new Date().toISOString()
    };
    await setDoc(doc(db, "logs", log.id), log);
};

// --- TICKETS ---
export const saveTicketToCloud = async (ticket: Ticket) => {
    await setDoc(doc(db, "tickets", ticket.id), sanitizeData(ticket));
};

export const updateTicketInCloud = async (id: string, updates: Partial<Ticket>) => {
    await updateDoc(doc(db, "tickets", id), sanitizeData(updates));
};

export const deleteTicketFromCloud = async (id: string) => {
    await deleteDoc(doc(db, "tickets", id));
};

export const subscribeToTickets = (callback: (tickets: Ticket[]) => void) => {
    const q = query(collection(db, "tickets"), orderBy("createdAt", "desc"));
    return onSnapshot(q, (snapshot) => {
        callback(snapshot.docs.map(d => d.data() as Ticket));
    });
};

