export const findCustomerByLoyaltyCode = async (code: string): Promise<Customer | null> => {
    const q = query(collection(db, "customers"), where("loyaltyCode", "==", code));
    const snap = await getDocs(q);
    return snap.empty ? null : (snap.docs[0].data() as Customer);
};

