export const subscribeToSettings = (
    onConfig: (cfg: AppConfig) => void,
    onServices: (srv: ServiceOption[]) => void,
    onPersonnel: (ppl: Personnel[]) => void
) => {
    const unsubCfg = onSnapshot(doc(db, "settings", "appConfig"), d => d.exists() && onConfig(d.data() as AppConfig));
    const unsubSrv = onSnapshot(doc(db, "settings", "services"), d => d.exists() && onServices((d.data() as any).list));
    const unsubPpl = onSnapshot(doc(db, "settings", "personnel"), d => d.exists() && onPersonnel((d.data() as any).list));
    return () => { unsubCfg(); unsubSrv(); unsubPpl(); };
};

