// --- STORAGE & FILE HELPERS ---
export const uploadFileWithProgress = (
    file: File,
    onProgress: (prog: number) => void,
    onSuccess: (url: string) => void,
    onError: (err: any) => void
) => {
    const fileRef = ref(storage, `uploads/${Date.now()}_${file.name}`);
    const uploadTask = uploadBytesResumable(fileRef, file);

    uploadTask.on('state_changed', 
        (snapshot) => onProgress((snapshot.bytesTransferred / snapshot.totalBytes) * 100),
        (error) => onError(error),
        () => getDownloadURL(uploadTask.snapshot.ref).then(onSuccess)
    );
};

export const compressImage = async (file: File, maxWidth: number, quality: number = 0.7): Promise<string> => {
    return new Promise((resolve) => {
        const reader = new FileReader();
        reader.readAsDataURL(file);
        reader.onload = (event) => {
            const img = new Image();
            img.src = event.target?.result as string;
            img.onload = () => {
                const canvas = document.createElement('canvas');
                let width = img.width;
                let height = img.height;
                if (width > maxWidth) {
                    height = (maxWidth / width) * height;
                    width = maxWidth;
                }
                canvas.width = width;
                canvas.height = height;
                const ctx = canvas.getContext('2d');
                ctx?.drawImage(img, 0, 0, width, height);
                resolve(canvas.toDataURL('image/jpeg', quality));
            };
        };
    });
};

// --- SYSTEM MAINTENANCE ---
export const backupSystemData = async (): Promise<boolean> => {
    try {
        const collections = ["tickets", "customers", "sales", "messages", "tasks", "meetings", "reports"];
        const backup: any = {};
        for (const col of collections) {
            const snap = await getDocs(collection(db, col));
            backup[col] = snap.docs.map(d => d.data());
        }
        const blob = new Blob([JSON.stringify(backup, null, 2)], { type: "application/json" });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `backup_${new Date().toISOString().split('T')[0]}.json`;
        a.click();
        return true;
    } catch (e) {
        return false;
    }
};

export const clearSystemData = async (): Promise<boolean> => {
    try {
        const collections = ["tickets", "customers", "sales", "messages", "tasks", "meetings", "reports", "logs"];
        for (const colName of collections) {
            const snap = await getDocs(collection(db, colName));
            for (const d of snap.docs) {
                await deleteDoc(doc(db, colName, d.id));
            }
        }
        return true;
    } catch (e) {
        return false;
    }
};

export const fetchAnalyticsData = async (): Promise<SystemLog[]> => {
    const q = query(collection(db, "logs"), orderBy("timestamp", "desc"), limit(500));
    const snap = await getDocs(q);
    return snap.docs.map(d => d.data() as SystemLog);
};

