interface Props {
  lang: Language;
  currentUser: Personnel;
  tickets: Ticket[];
  services: ServiceOption[];
  personnel: Personnel[];
  customers: Customer[];
  messages: InternalMessage[];
  tasks: Task[];
  meetings: Meeting[];
  kpis: KPI[];
  config: AppConfig;
  onCreateTicket: (ticket: Ticket) => Promise<void>;
  onUpdateTicket: (id: string, updates: Partial<Ticket>, actorName: string, actionNote?: string, visibility?: 'public' | 'internal') => Promise<void>;
  onDeleteTicket: (id: string) => Promise<void>;
  onUpdateServices: (services: ServiceOption[]) => Promise<void>;
  onUpdatePersonnel: (personnel: Personnel[]) => Promise<void>;
  onUpdateCustomers: (customers: Customer[]) => Promise<void>;
  onEditCustomer: (id: string, updates: Partial<Customer>) => Promise<void>;
  onDeleteCustomer: (id: string) => Promise<void>;
  onUpdateConfig: (config: AppConfig) => Promise<void>;
  onLogout: () => void;
}

type TabKey = 'overview' | 'projects' | 'services' | 'personnel' | 'customers' | 'settings' | 'financial' | 'messages' | 'tasks' | 'meetings' | 'logs' | 'reports' | 'kpi' | 'forms' | 'sales' | 'staff_reports' | 'goals';

export const AdminDashboard: React.FC<Props> = ({ 
  lang, currentUser, tickets, services, personnel, customers, messages, tasks, meetings, kpis, config,
  onUpdateTicket, onDeleteTicket, onUpdateServices, onUpdatePersonnel, onUpdateCustomers, 
  onEditCustomer, onDeleteCustomer, onUpdateConfig, onLogout 
}) => {
  const [activeTab, setActiveTab] = useState<TabKey>('overview');

  const isMaster = currentUser.username === 'master';
  const isAdmin = currentUser.roles.includes('مدیر') || isMaster;

  const NavButton = ({ tab, icon: Icon, label }: { tab: TabKey, icon: any, label: string }) => (
    <button 
      onClick={() => setActiveTab(tab)} 
      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl transition-all ${activeTab === tab ? 'bg-indigo-600 text-white shadow-md' : 'text-gray-600 hover:bg-gray-50'}`}
    >
      <Icon className="w-5 h-5" />
      <span className="font-medium">{label}</span>
    </button>
  );

  return (
    <div className="flex flex-col md:flex-row gap-6 min-h-[calc(100vh-100px)]">
      {/* Sidebar */}
      <div className="w-full md:w-72 shrink-0 space-y-2">
         <div className="bg-white p-4 rounded-2xl border border-gray-100 shadow-sm mb-4">
            <div className="flex items-center gap-3 mb-4">
                <div className="w-12 h-12 rounded-full bg-indigo-100 flex items-center justify-center text-indigo-600 font-bold">
                    {currentUser.avatar ? <img src={currentUser.avatar} className="w-full h-full rounded-full object-cover" /> : currentUser.fullName.charAt(0)}
                </div>
                <div className="min-w-0">
                    <div className="font-bold text-gray-900 truncate">{currentUser.fullName}</div>
                    <div className="text-xs text-gray-500 truncate">{currentUser.roles.join(', ')}</div>
                </div>
            </div>
            <button onClick={onLogout} className="w-full py-2 bg-red-50 text-red-600 rounded-lg text-sm font-bold hover:bg-red-100 transition-colors">خروج از سیستم</button>
         </div>

         <div className="space-y-1">
            <NavButton tab="overview" icon={IconLayout} label="میز کار (Overview)" />
            {isAdmin && <NavButton tab="services" icon={IconBriefcase} label="مدیریت سرویس‌ها" />}
            {isAdmin && <NavButton tab="personnel" icon={IconUsers} label="مدیریت پرسنل" />}
            {(isAdmin || currentUser.permissions.canViewCustomers) && <NavButton tab="customers" icon={IconUsers} label="بانک مشتریان" />}
