            <NavButton tab="tasks" icon={IconList} label="وظایف و امور" />
            <NavButton tab="meetings" icon={IconCalendarClock} label="تقویم جلسات" />
            <NavButton tab="sales" icon={IconMoney} label="پنل فروش" />
            <NavButton tab="reports" icon={IconClipboard} label="گزارش عملکرد" />
            <NavButton tab="goals" icon={IconTarget} label="ردیاب اهداف (Goals)" />
            {isAdmin && <NavButton tab="staff_reports" icon={IconBarChart2} label="آنالیز عملکرد تیمی" />}
            {isAdmin && <NavButton tab="kpi" icon={IconTrendingUp} label="شاخص‌های KPI" />}
            {isAdmin && <NavButton tab="settings" icon={IconSettings} label="تنظیمات سیستم" />}
